import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int k = Integer.parseInt(st.nextToken()); String s = br.readLine(); int count0 = 0; int count1 = 0; for (char c : s.toCharArray()) { if (c == '0') count0++; else count1++; } int[] chainLengths = new int[k]; for (int i = 0; i < n; i++) { chainLengths[i % k]++; } int min0 = 0; int min1 = 0; for (int len : chainLengths) { min0 += len / 2; min1 += len / 2; if (len % 2 != 0) { if (min0 <= min1) min0++; else min1++; } } if (count0 >= min0 && count1 >= min1) { out.println("Yes"); } else { out.println("No"); } } out.flush(); out.close(); } }